#!/usr/bin/env python3
import requests
import base64
import sys
from urllib.parse import urlencode
import json

def register_user(username, password):
    url = "http://crypto.chal.csaw.io:8000/register"
    data = {
        'username': username,
        'password': password
    }

    # Try different headers to force CBC
    headers = {
        'Content-Type': 'application/x-www-form-urlencoded',
        'User-Agent': 'OldBrowser/1.0',
        'Accept': '*/*'
    }

    response = requests.post(url, data=data, headers=headers, allow_redirects=False)
    print(f"Register Response Status: {response.status_code}")
    print("Cookies:", response.cookies.get_dict())
    print("Headers:", response.headers)
    return response

def login_user(username, password):
    url = "http://crypto.chal.csaw.io:8000/login"
    data = {
        'username': username,
        'password': password
    }

    # Try different headers combinations
    headers = [
        {
            'Content-Type': 'application/x-www-form-urlencoded',
            'User-Agent': 'OldBrowser/1.0',
            'Accept': '*/*'
        },
        {
            'Content-Type': 'application/x-www-form-urlencoded',
            'User-Agent': 'Legacy/1.0',
            'Accept': 'text/html'
        },
        {
            'Content-Type': 'application/x-www-form-urlencoded',
            'User-Agent': 'Mozilla/4.0',
            'Accept': 'text/html',
            'Legacy-Mode': 'true'
        }
    ]

    for header in headers:
        print(f"\nTrying headers: {header}")
        response = requests.post(url, data=data, headers=header, allow_redirects=False)
        print(f"Login Response Status: {response.status_code}")
        print("Cookies:", response.cookies.get_dict())
        if 'session' in response.cookies:
            cookie = response.cookies['session']
            try:
                decoded = base64.b64decode(cookie)
                print("Cookie length:", len(decoded))
                print("Cookie hex:", decoded.hex())
            except:
                print("Failed to decode cookie")

def main():
    username = "testuser123"
    password = "testpass123"

    print("Attempting to register new user...")
    register_response = register_user(username, password)

    print("\nAttempting to login...")
    login_response = login_user(username, password)

if __name__ == "__main__":
    main()

