#!/usr/bin/env python3
import requests
import base64
import sys
from urllib.parse import urlencode, unquote
import json

def analyze_cookie(cookie_str):
    try:
        # URL decode the cookie first
        decoded = unquote(cookie_str)
        # Split by dots as it seems to be in format: iv.nonce.ciphertext
        parts = decoded.split('.')
        print(f"Cookie parts: {len(parts)}")
        for i, part in enumerate(parts):
            try:
                decoded_part = base64.b64decode(part)
                print(f"Part {i} length: {len(decoded_part)}")
                print(f"Part {i} hex: {decoded_part.hex()}")
            except:
                print(f"Part {i} not base64")
    except Exception as e:
        print(f"Error analyzing cookie: {e}")

def try_force_cbc(username, password):
    url = "http://crypto.chal.csaw.io:8000/login"
    data = {
        'username': username,
        'password': password
    }

    headers_list = [
        {
            'Content-Type': 'application/x-www-form-urlencoded',
            'User-Agent': 'Mozilla/4.0 (compatible; MSIE 6.0; Windows NT 5.1)',
            'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8',
            'Connection': 'keep-alive',
            'Downgrade-Insecure-Requests': '1',
            'Legacy-Crypto': 'true',
            'Force-Cipher': 'CBC'
        },
        {
            'Content-Type': 'application/x-www-form-urlencoded',
            'User-Agent': 'Netscape/4.78 [en]',
            'Accept': '*/*',
            'Cipher-Mode': 'CBC',
            'Legacy': 'true'
        },
        {
            'Content-Type': 'application/x-www-form-urlencoded',
            'User-Agent': 'Mozilla/3.0 (compatible)',
            'Accept': 'text/html',
            'Security-Level': 'legacy',
            'Encryption-Mode': 'CBC'
        }
    ]

    # Try both GET and POST methods
    methods = ['GET', 'POST']

    for method in methods:
        for headers in headers_list:
            print(f"\nTrying {method} with headers: {headers}")

            if method == 'GET':
                response = requests.get(url + '?' + urlencode(data), headers=headers, allow_redirects=False)
            else:
                response = requests.post(url, data=data, headers=headers, allow_redirects=False)

            print(f"Response Status: {response.status_code}")
            print("Response Headers:", response.headers)

            if 'auth' in response.cookies:
                cookie = response.cookies['auth']
                print("\nFound auth cookie:")
                analyze_cookie(cookie)

def main():
    username = "testuser456"
    password = "testpass456"

    print("Attempting to force CBC mode...")
    try_force_cbc(username, password)

if __name__ == "__main__":
    main()

